"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["43517"],{863(e){e.exports=JSON.parse('{"id":"F442","slug":"lc-discounting-cost","name":"Letter of Credit and Discounting: All-In Cost","subject":"International Finance","section":"Global Finance","topic":"Trade finance: letters of credit","level":"Beginner","aliases":["trade finance","letter of credit fees","banker\'s acceptance","receivables discounting"],"formula":{"latex":"\\\\text{Discount}=F\\\\,d\\\\,\\\\frac{t}{360},\\\\quad \\\\text{All-in rate}=\\\\frac{\\\\text{Costs}}{F-\\\\text{Costs}}\\\\times\\\\frac{365}{t}","also":[],"text":"Discount = face value x discount rate x days / 360; Total cost = discount + issuance fee (% of face) + confirmation fee (% a year x days / 360 x face); Net proceeds = face - total cost; All-in annualized cost = total cost / net proceeds x 365 / days"},"symbols":[{"symbol":"F","meaning":"Face value of the letter of credit or acceptance","unit":"money"},{"symbol":"d","meaning":"Bank discount rate (quoted on face value, 360-day year)","unit":"per year"},{"symbol":"t","meaning":"Days until payment (usance period)","unit":"days"},{"symbol":"fees","meaning":"Issuance fee and confirmation fee","unit":"percent"}],"when_to_use":"Use it to see what a seller pays to be paid early on an export under a letter of credit. The bank pays the seller now, less a discount, and collects the buyer\'s bank payment later. A bank-quoted discount rate understates the true cost, since it applies to face value and not to the amount actually advanced, and fees add to it. Compare all-in rates, not quoted rates.","worked_example":{"problem":"A seller discounts a 90-day, 500,000 letter of credit at a 6% bank discount rate, with a 0.75% issuance fee and a confirmation fee of 0.30% a year.","inputs":{"f":500000,"t":90,"d":6,"iss":0.75,"cnf":0.3},"steps":[{"label":"Discount = F x d x t / 360","working":"500000 x 0.06 x 90 / 360","value":"7,500.00"},{"label":"Issuance and confirmation fees","working":"500000 x 0.0075+500000 x 0.003 x 90 / 360","value":"4,125.00"},{"label":"Total cost","working":"7500+4125","value":"11,625.00"},{"label":"Net proceeds","working":"500000-11625","value":"488,375.00"},{"label":"All-in annualized cost = cost / net x 365 / t","working":"11625 / 488375 x 365 / 90","value":"9.65%"}],"answer":"The discount is 7,500.00. Adding the issuance fee and confirmation fee brings total costs to 11,625.00, so the seller receives 488,375.00. The all-in cost is 9.65% annualized, against the quoted 6%."},"calculator":{"available":true,"inputs":[{"id":"f","label":"Face value","unit":"money","type":"number","default":500000,"hint":""},{"id":"t","label":"Days to payment","unit":"days","type":"number","default":90,"hint":"","min":1},{"id":"d","label":"Discount rate","unit":"%","type":"number","default":6,"hint":""},{"id":"iss","label":"Issuance fee (flat, of face)","unit":"%","type":"number","default":0.75,"hint":""},{"id":"cnf","label":"Confirmation fee (per year)","unit":"%","type":"number","default":0.3,"hint":""}],"checks":[{"expr":"f>0 and t>0","message":"The face value and days must be above zero."}],"steps":[{"id":"disc","label":"Discount = F x d x t / 360","expr":"f*d*t/360","format":"money"},{"id":"fees","label":"Issuance and confirmation fees","expr":"f*iss+f*cnf*t/360","format":"money"},{"id":"cost","label":"Total cost","expr":"disc+fees","format":"money"},{"id":"net","label":"Net proceeds","expr":"f-cost","format":"money"},{"id":"allin","label":"All-in annualized cost = cost / net x 365 / t","expr":"cost/net*365/t","format":"pct2"}],"results":["disc","cost","net","allin"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"disc":7500,"fees":4125,"cost":11625,"net":488375,"allin":0.09653613172937463}},"finder":{"finds":"What early payment under a letter of credit really costs","needs":"Face value, days, discount rate, fees"},"related":[{"slug":"money-market-yields","name":"T-Bill Discount Yield and Money Market Yields"},{"slug":"cost-of-trade-credit","name":"Cost of Skipping an Early-Payment Discount"},{"slug":"supply-chain-finance-return","name":"Early-Payment Discount Return (Supply Chain Finance)"}],"related_ids":["F283","F194","F196"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Discount</mtext><mo>=</mo><mi>F</mi><mtext>\u2009</mtext><mi>d</mi><mtext>\u2009</mtext><mfrac><mi>t</mi><mn>360</mn></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>All-in\xa0rate</mtext><mo>=</mo><mfrac><mtext>Costs</mtext><mrow><mi>F</mi><mo>\u2212</mo><mtext>Costs</mtext></mrow></mfrac><mo>\xd7</mo><mfrac><mn>365</mn><mi>t</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Discount}=F\\\\,d\\\\,\\\\frac{t}{360},\\\\quad \\\\text{All-in rate}=\\\\frac{\\\\text{Costs}}{F-\\\\text{Costs}}\\\\times\\\\frac{365}{t}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"lease-liability-pv","name":"Lease Liability and First-Year Expense (IFRS 16 / ASC 842)"},"next":{"slug":"life-insurance-need","name":"Life Insurance Needs Analysis"},"lesson":null,"total":522}')}}]);